#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    string s, t;
    cin >> n >> k >> s >> t;

    const char a = t[0];
    const char b = t[1];

    if (a == b) {
        int count = 0;
        for (char c : s) {
            count += (c == a);
        }
        count = min(n, count + k);
        cout << 1LL * count * (count - 1) / 2 << '\n';
        return 0;
    }

    k = min(k, n);
    vector<vector<int>> dp(k + 1, vector<int>(n + 1, -1));
    vector<vector<int>> nextDp(k + 1, vector<int>(n + 1, -1));
    dp[0][0] = 0;

    for (char c : s) {
        for (auto& row : nextDp) {
            fill(row.begin(), row.end(), -1);
        }

        for (int used = 0; used <= k; ++used) {
            for (int countA = 0; countA <= n; ++countA) {
                if (dp[used][countA] == -1) {
                    continue;
                }

                int newCountA = countA + (c == a);
                int newValue = dp[used][countA] + (c == b ? countA : 0);
                nextDp[used][newCountA] =
                    max(nextDp[used][newCountA], newValue);

                if (used < k) {
                    nextDp[used + 1][countA + 1] =
                        max(nextDp[used + 1][countA + 1],
                            dp[used][countA]);

                    nextDp[used + 1][countA] =
                        max(nextDp[used + 1][countA],
                            dp[used][countA] + countA);
                }
            }
        }

        dp.swap(nextDp);
    }

    int answer = 0;
    for (int used = 0; used <= k; ++used) {
        for (int countA = 0; countA <= n; ++countA) {
            answer = max(answer, dp[used][countA]);
        }
    }

    cout << answer << '\n';
    return 0;
}

