    const char a = t[0];
    const char b = t[1];

    if (a == b) {
        int occurrences = 0;
        for (char c : s) {
            occurrences += (c == a);
        }

        occurrences = min(n, occurrences + k);
        cout << 1LL * occurrences * (occurrences - 1) / 2 << '\n';
        return 0;
    }

    const ll NEG = -(1LL << 60);

    vector<vector<ll>> dp(k + 1, vector<ll>(n + 1, NEG));
    vector<vector<ll>> nextDp(k + 1, vector<ll>(n + 1, NEG));

    dp[0][0] = 0;

    for (int i = 0; i < n; ++i) {
        for (auto& row : nextDp) {
            fill(row.begin(), row.end(), NEG);
