            for (int countA = 0; countA <= i; ++countA) {
                if (dp[used][countA] == NEG) {
                    continue;
                }

                ll value = dp[used][countA];

                int nextCountA = countA + (s[i] == a);
                ll addedPairs = (s[i] == b ? countA : 0);
                nextDp[used][nextCountA] =
                    max(nextDp[used][nextCountA], value + addedPairs);

                int costA = (s[i] != a);
                if (used + costA <= k) {
                    nextDp[used + costA][countA + 1] =
                        max(nextDp[used + costA][countA + 1], value);
                }

                int costB = (s[i] != b);
                if (used + costB <= k) {
                    nextDp[used + costB][countA] =
                        max(nextDp[used + costB][countA], value + countA);
                }
            }
        }

        dp.swap(nextDp);
    }

    ll answer = 0;
    for (int used = 0; used <= k; ++used) {
        for (int countA = 0; countA <= n; ++countA) {
            answer = max(answer, dp[used][countA]);
        }
    }

    cout << answer << '\n';
    return 0;
}

