#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int N = 511;

ll dp[2][N][N];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    string s, t;
    cin >> n >> k >> s >> t;

    char a = t[0], b = t[1];

    if (a == b) {
        ll count = 0;
        for (char c : s) {
            count += (c == a);
        }
        count = min<ll>(n, count + k);
        cout << count * (count - 1) / 2 << '\n';
        return 0;
    }

    memset(dp, -1, sizeof(dp));
    dp[0][0][0] = 0;

    for (int i = 0; i < n; ++i) {
        int next = (i + 1) & 1;
        int current = i & 1;
        memset(dp[next], -1, sizeof(dp[next]));

        for (int used = 0; used <= min(k, i); ++used) {
            for (int countA = 0; countA <= i; ++countA) {
                ll value = dp[current][used][countA];
                if (value < 0) continue;

                int newCountA = countA + (s[i] == a);
                ll newValue = value + (s[i] == b ? countA : 0);
                dp[next][used][newCountA] =
                    max(dp[next][used][newCountA], newValue);

                if (used < k) {
                    dp[next][used + 1][countA + 1] =
                        max(dp[next][used + 1][countA + 1], value);

                    dp[next][used + 1][countA] =
                        max(dp[next][used + 1][countA], value + countA);
                }
            }
        }
    }

    ll answer = 0;
    for (int used = 0; used <= k; ++used) {
        for (int countA = 0; countA <= n; ++countA) {
            answer = max(answer, dp[n & 1][used][countA]);
        }
    }

    cout << answer << '\n';
    return 0;
}

